73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper) {
86	        this.clinicService = clinicService;
87	        this.ownerMapper = ownerMapper;
88	        this.petMapper = petMapper;
89	        this.visitMapper = visitMapper;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        // Normalize the address up front so every downstream use (the required-field check,
121	        // household-duplicate detection, the shared household id and the stored/returned value)
122	        // works from the same canonical form.
123	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
124	        List<String> missingFields = new ArrayList<>();
125	        if (isBlank(ownerFieldsDto.getFirstName())) {
126	            missingFields.add("firstName");
127	        }
128	        if (isBlank(ownerFieldsDto.getLastName())) {
129	            missingFields.add("lastName");
130	        }
131	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
132	        if (isBlank(normalizedAddress)) {
133	            missingFields.add("address");
134	        }
135	        if (isBlank(ownerFieldsDto.getCity())) {
136	            missingFields.add("city");
137	        }
138	        if (isBlank(ownerFieldsDto.getTelephone())) {
139	            missingFields.add("telephone");
140	        }
141	        if (!missingFields.isEmpty()) {
142	            throw new InvalidOwnerFieldsException(missingFields);
143	        }
144	        // Determine the effective registration date up front so every downstream use (the daily
145	        // create-limit, the stored value and anything derived from it such as the membership number's
146	        // year segment) works from the same business-day-adjusted date. The effective date is the
147	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
148	        // forward to the following Monday.
149	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
150	            ? ownerFieldsDto.getRegistrationDate()
151	            : LocalDate.now();
152	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
153	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
154	        // already carry this adjusted business day's registration date, no further owners may be
155	        // created for that day.
156	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
157	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
158	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
159	        }
160	        // Flag a bulk signup once more than 80 owners have already been created for this
161	        // business day, sharing the same daily accumulation path as the create-limit rule above.
162	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
163	        // Reject the request when the owner's city is already full: a city that already holds the
164	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
165	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
166	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
167	        }
168	        // Normalize the telephone into E.164 form; a number that cannot form a valid
169	        // E.164 value is rejected with a 400.
170	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
171	        // Email is optional; when present it must be a syntactically valid address and is
172	        // stored lower-cased. An invalid address is rejected with a 400.
173	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
174	        // Reject the request if the E.164 telephone is already used by any other owner.
175	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
176	            .map(Owner::getTelephone)
177	            .filter(existing -> existing != null)
178	            .anyMatch(normalizedTelephone::equals);
179	        if (telephoneInUse) {
180	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
181	        }
182	        // Reject the request if the (lower-cased) email is already used by any other owner. Stored
183	        // emails are already normalized to lower case, but compare case-insensitively defensively.
184	        if (normalizedEmail != null) {
185	            boolean emailInUse = this.clinicService.findAllOwners().stream()
186	                .map(Owner::getEmail)
187	                .filter(existing -> existing != null)
188	                .anyMatch(normalizedEmail::equalsIgnoreCase);
189	            if (emailInUse) {
190	                throw new DuplicateOwnerEmailException(normalizedEmail);
191	            }
192	        }
193	        // Household handling for a matching last name + address (compared case-insensitively with
194	        // collapsed whitespace). By default such a request is rejected as a duplicate household;
195	        // when the caller opts in via 'sharesHousehold' the owner is instead admitted into the shared
196	        // household and every member (the new owner and any existing ones) is stamped with the same
197	        // stable 'householdId'.
198	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
199	        String householdId = null;
200	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
201	            householdId = householdId(normalizedLastName, normalizedAddress);
202	            // Backfill the shared identifier onto any existing member of this household so the whole
203	            // household carries the same stable value.
204	            for (Owner existing : this.clinicService.findAllOwners()) {
205	                if (collapse(existing.getLastName()).equals(normalizedLastName)
206	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
207	                    && !householdId.equals(existing.getHouseholdId())) {
208	                    existing.setHouseholdId(householdId);
209	                    this.clinicService.saveOwner(existing);
210	                }
211	            }
212	        } else {
213	            boolean householdInUse = this.clinicService.findAllOwners().stream()
214	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
215	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress));
216	            if (householdInUse) {
217	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
218	            }
219	        }
220	        HttpHeaders headers = new HttpHeaders();
221	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
222	        owner.setAddress(normalizedAddress);
223	        owner.setTelephone(normalizedTelephone);
224	        owner.setEmail(normalizedEmail);
225	        owner.setHouseholdId(householdId);
226	        // Record how many existing owners (before this create) share this owner's first and last
227	        // name, compared case-insensitively. Computed against the current owners so the new owner
228	        // itself is never counted.
229	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
230	        // Record the size of this owner's household (owners sharing the same householdId) after this
231	        // create: the existing members already stamped with the shared identifier plus this new
232	        // owner. An owner not admitted into any household is a household of one.
233	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
234	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
235	        owner.setBulkSignupWarning(bulkSignupWarning);
236	        // Store the business-day-adjusted effective registration date computed above. This defaults
237	        // to the server's current date when none was supplied and rolls any weekend date forward to
238	        // the following Monday, so everything derived from it (e.g. the membership number's year
239	        // segment) uses the adjusted date.
240	        owner.setRegistrationDate(effectiveRegistrationDate);
241	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
242	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
243	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
244	        // owners already in that city.
245	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
246	        this.clinicService.saveOwner(owner);
247	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
248	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
249	        // customer code, the effective registration date and the numeric membership level.
250	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
251	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
252	        headers.setLocation(UriComponentsBuilder.newInstance()
253	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
254	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
